import base64, io, zipfile, os, sys, faulthandler
from pathlib import Path
for variable in ('OMP_NUM_THREADS', 'OPENBLAS_NUM_THREADS', 'MKL_NUM_THREADS', 'NUMEXPR_NUM_THREADS'):
    os.environ[variable] = '2'
os.environ['PYTHONUNBUFFERED'] = '1'
if hasattr(sys.stdout, 'reconfigure'):
    sys.stdout.reconfigure(line_buffering=True)
faulthandler.enable()
print('Appendix bootstrap: CPU threads=2; extracting source', flush=True)
project = Path('/kaggle/working/project')
project.mkdir(exist_ok=False)
with zipfile.ZipFile(io.BytesIO(base64.b64decode(''))) as archive:
    archive.extractall(project)

"""Run an appendix section against frozen Kaggle train/validation artifacts."""
import hashlib
import importlib.metadata
import json
import os
from pathlib import Path
import subprocess
import sys
import traceback


def checkpoint(output, stage, **details):
    state = {'stage': stage, **details}
    (output / 'progress.json').write_text(json.dumps(state, indent=2) + '\n')
    print(json.dumps(state), flush=True)


def execute(project, section, expected_manifest, expected_metadata, expected_split):
    try:
        return run(project, section, expected_manifest, expected_metadata, expected_split)
    except BaseException as error:
        output = Path('/kaggle/working') / f'appendix_{section}'
        output.mkdir(exist_ok=True)
        progress = output / 'progress.json'
        failure = {'status': 'failed', 'section': section,
            'progress': json.loads(progress.read_text()) if progress.exists() else {},
            'error_type': type(error).__name__, 'error': str(error),
            'traceback': traceback.format_exc()}
        (output / 'failure.json').write_text(json.dumps(failure, indent=2) + '\n')
        print(json.dumps(failure, indent=2), flush=True)
        raise


def run(project, section, expected_manifest, expected_metadata, expected_split):
    os.environ['MPLBACKEND'] = 'Agg'
    os.environ['MPLCONFIGDIR'] = '/kaggle/working/matplotlib-cache'
    output = Path('/kaggle/working') / f'appendix_{section}'
    output.mkdir(exist_ok=False)
    checkpoint(output, 'verify_source')
    hashes = json.loads((project / 'source_hashes.json').read_text())
    for relative, expected in hashes.items():
        with (project / relative).open('rb') as stream:
            if hashlib.file_digest(stream, 'sha256').hexdigest() != expected:
                raise RuntimeError(f'Source checksum mismatch: {relative}')
    checkpoint(output, 'tests')
    test = subprocess.run([sys.executable, '-m', 'pytest', '-q', str(project / 'tests'),
        f'--junitxml={output / "tests.xml"}'], cwd=project, capture_output=True, text=True)
    (output / 'tests.log').write_text(test.stdout + test.stderr)
    print(test.stdout + test.stderr, flush=True)
    test.check_returncode()
    checkpoint(output, 'verify_frozen_inputs')
    sys.path.insert(0, str(project / 'src'))
    from pubg_weapon.appendix import run_appendix
    from pubg_weapon.io import file_sha256, read_json, write_json
    import pandas as pd
    candidates = [p for p in Path('/kaggle/input').rglob('metadata.json')
                  if p.parent.name == 'models' and p.parent.parent.name == 'full']
    if len(candidates) != 1:
        raise RuntimeError(f'Expected one frozen full run, found {candidates}')
    metadata_path = candidates[0]
    baseline = metadata_path.parent
    processed = baseline.parent / 'processed'
    if file_sha256(metadata_path) != expected_metadata or file_sha256(processed / 'dataset_manifest.json') != expected_manifest:
        raise RuntimeError('Attached source is not the frozen main run version 1')
    manifest = read_json(processed / 'dataset_manifest.json')
    if manifest['source_match_splits_sha256'] != expected_split:
        raise RuntimeError('Frozen source split differs')
    metadata = read_json(metadata_path)
    for package in ('numpy', 'pandas', 'scikit-learn', 'pyarrow', 'joblib'):
        if importlib.metadata.version(package) != metadata['versions'][package]:
            raise RuntimeError(f'Frozen pipeline environment differs: {package}')
    allowed = {str((processed / f'{name}.parquet').resolve()) for name in ('train', 'validation')}
    reads = []
    original = pd.read_parquet

    def guarded_read(path, *args, **kwargs):
        if str(Path(path).resolve()) not in allowed:
            raise RuntimeError('Appendix may only read frozen train/validation parquet')
        reads.append(Path(path).name)
        checkpoint(output, 'fit_and_validation', parquet_reads=reads.copy())
        return original(path, *args, **kwargs)

    pd.read_parquet = guarded_read
    try:
        checkpoint(output, 'fit_and_validation', parquet_reads=reads.copy())
        summary = run_appendix(processed, baseline, output / 'results', section, jobs=2)
    finally:
        pd.read_parquet = original
    if reads != ['train.parquet', 'validation.parquet']:
        raise RuntimeError(f'Unexpected data reads: {reads}')
    if summary['training_rows'] != 1_000_000 or summary['validation_rows'] != 480_891:
        raise RuntimeError('Appendix must use the exact full-size frozen data')
    readiness = {'status': 'passed', 'section': section, 'test_read': False, 'parquet_reads': reads,
        'source_kernel': 'sangtranminh211/pubg-loadout-history-full-final-20261022', 'source_version': 1,
        'source_hashes': hashes, 'tests_returncode': test.returncode, 'summary': summary,
        'versions': {p: importlib.metadata.version(p) for p in ('numpy','pandas','scikit-learn','pyarrow','joblib')}}
    write_json(output / 'readiness.json', readiness)
    checkpoint(output, 'complete', parquet_reads=reads)
    print(json.dumps(readiness, indent=2), flush=True)

execute(project, 'hgb_grid', '5b95abab6f2773161d66f2504cd71b86a51ea806b16795edb5e1d94b4f906fbe', 'a87f96d211d528569dbc117ff4ed61df708c8fa7528f1926d86e86d54b48dc47', '3cd3e1a76c8679b510ee791bbd280a3684a51ffc03676c39ffbcc7466296c8ce')
